function flattenIssueObjects(value){
  if(value==null)return [];
  if(Array.isArray(value))return value.flatMap(flattenIssueObjects);
  if(typeof value==='object'){
    if(typeof value.message==='string'||typeof value.error==='string')return [value];
    return Object.values(value).flatMap(flattenIssueObjects);
  }
  return [];
}
function issueLines(job){
  const list=[];
  for(const item of job?.delivery?.jobs??[]){
    if(!['failed','ambiguous'].includes(item.status))continue;
    const failures=Array.isArray(item.result?.payload?.failures)?item.result.payload.failures:[];
    const errors=Array.isArray(item.result?.payload?.errors)?item.result.payload.errors:[];
    const fallback=item.result?.payload?.message??item.result?.payload?.error??item.result?.message??item.result?.error;
    list.push({label:`${PLATFORM[item.platform]?.name??item.platform??'Profile'}${item.account_id?` · ${item.account_id}`:''}`,status:item.status,job_id:item.job_id,message:failures[0]?.message??errors[0]?.message??fallback??'Publer marked this profile as failed.'});
  }
  if(job?.error)try{const parsed=JSON.parse(job.error),items=flattenIssueObjects(parsed);if(items.length)for(const item of items)list.push({label:`${PLATFORM[item.platform]?.name??item.platform??item.provider??'Publer'}${item.account_name?` · ${item.account_name}`:item.account_id?` · ${item.account_id}`:''}`,status:'failed',job_id:item.job_id,message:item.message??item.error});else list.push({label:'Publer',status:'failed',message:job.error});}catch{list.push({label:'Publer',status:'failed',message:job.error});}
  return list;
}
