async function inspectFile(file){
  const url=URL.createObjectURL(file);try{return await new Promise((resolve,reject)=>{
    const video=file.type.startsWith('video/'),node=document.createElement(video?'video':'img');const timer=setTimeout(()=>reject(new Error('Cannot read this media. Try a JPG, PNG or MP4.')),15000);
    const done=()=>{clearTimeout(timer);resolve({width:video?node.videoWidth:node.naturalWidth,height:video?node.videoHeight:node.naturalHeight,duration:video?node.duration:0,type:video?'video':'image',name:file.name,size:file.size});};
    node.onerror=()=>{clearTimeout(timer);reject(new Error('This browser cannot read the file. Convert videos to MP4/H.264.'));};if(video){node.preload='metadata';node.onloadedmetadata=done;}else node.onload=done;node.src=url;
  });}finally{URL.revokeObjectURL(url);}
}
async function captureVideoFrames(file){
  const url=URL.createObjectURL(file);
  try{return await new Promise((resolve,reject)=>{
    const video=document.createElement('video'),canvas=document.createElement('canvas'),frames=[],points=[.1,.5,.85];let index=0;video.muted=true;video.preload='metadata';
    const fail=setTimeout(()=>reject(new Error('Could not capture cover frames. Try an MP4/H.264 file.')),30000);
    video.onloadedmetadata=()=>{canvas.width=video.videoWidth||1080;canvas.height=video.videoHeight||1920;video.currentTime=Math.max(.1,(video.duration||1)*points[index]);};
    video.onseeked=()=>{canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(blob)frames.push(new File([blob],`${file.name.replace(/\.[^.]+$/,'')}-cover-${index+1}.jpg`,{type:'image/jpeg'}));index++;if(index<points.length)video.currentTime=Math.max(.1,(video.duration||1)*points[index]);else{clearTimeout(fail);resolve(frames);}},'image/jpeg',.82);};
    video.onerror=()=>{clearTimeout(fail);reject(new Error('This browser cannot read the video for cover frames.'));};video.src=url;
  });}finally{URL.revokeObjectURL(url);}
}

